def get_env(key, default=None):
    """
    Read a value from a .env file and return it or a default if the key is not found.

    Args:
        key (str): The key to look up in the .env file.
        default (str, optional): The default value to return if the key is not found.

    Returns:
        str: The value of the key from the .env file or the default.
    """
    try:
        with open('.env', 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    parts = line.split('=', 1)
                    if len(parts) == 2:
                        env_key, env_value = parts
                        if env_key == key:
                            return env_value
    except FileNotFoundError:
        pass
    return default

