import difflib

def find_closest(query, names):
    best_match = None
    best_ratio = 0.0

    for name in names:
        ratio = difflib.SequenceMatcher(None, query, name).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best_match = name

    return best_match

import bcrypt

def hash_password(password: str) -> bytes:
    """Hash a password using bcrypt."""
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())

def verify_password(password: str, stored_hash: bytes) -> bool:
    """Verify a password against a stored hash."""
    return bcrypt.checkpw(password.encode('utf-8'), stored_hash)

def levenshtein(s1, s2):
    if len(s1) < len(s2):
        return levenshtein(s2, s1)
    # Create a 2D table to store the edit distances
    prev_row = [i for i in range(len(s2) + 1)]
    for i, char1 in enumerate(s1):
        current_row = [0] * (len(s2) + 1)
        current_row[0] = i + 1  # Cost of deletions
        for j, char2 in enumerate(s2):
            cost = 0 if char1 == char2 else 1
            current_row[j + 1] = min(
                current_row[j] + 1,  # Insert
                prev_row[j + 1] + 1,  # Delete
                prev_row[j] + cost   # Substitute
            )
        prev_row = current_row
    return prev_row[-1]

def find_closest_match_custom(query, names, n=1):
    closest = []
    for name in names:
        distance = levenshtein(query, name)
        closest.append((name, distance))
    # Sort by distance and return the top n matches
    closest.sort(key=lambda x: x[1])
    return [name for name, _ in closest[:n]]

