    # Check the length of the digits
    if len(digits) == 10:
        return f"+1 {digits[0:3]} {digits[3:6]} {digits[6:10]}"
    elif len(digits) == 11:
        # Assume the first digit is the country code
        return f"+1 {digits[1:4]} {digits[4:7]} {digits[7:11]}"
