import time
from functools import wraps

def cache_with_ttl(ttl_seconds):
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate a hashable key based on the function's arguments
            key = (args, kwargs)

            # Check if the key exists in the cache and is still valid
            if key in cache:
                stored_time = cache[key][1]
                if time.time() - stored_time < ttl_seconds:
                    return cache[key][0]

            # If the result is not in the cache or expired, compute it
            result = func(*args, **kwargs)

            # Store the result and the current timestamp
            cache[key] = (result, time.time())

            return result

        return wrapper

    return decorator

